// Three structurally different entry points on one throwaway route (?variant=A/B/C).
// Question: which visual learning experience helps a reader without ML training background start?
const $=s=>document.querySelector(s);
const params=new URLSearchParams(location.search);
const state={variant:['A','B','C'].includes(params.get('variant'))?params.get('variant'):'A',page:params.get('page')||'home',stage:0,scene:0,playing:false,completed:false,quiz:null,learningRate:.2};
let playTimer=null,modalReturn=null;
const icons={
 data:'<path d="M5 5h15v19H5zM9 10h7M9 14h7M9 18h4"/><path d="M20 9h5v19H10v-4"/>',
 token:'<rect x="3" y="6" width="10" height="8" rx="2"/><rect x="17" y="6" width="10" height="8" rx="2"/><rect x="3" y="18" width="16" height="8" rx="2"/><path d="M23 18v8"/>',
 model:'<circle cx="6" cy="8" r="2"/><circle cx="6" cy="23" r="2"/><circle cx="16" cy="5" r="2"/><circle cx="16" cy="16" r="2"/><circle cx="16" cy="27" r="2"/><circle cx="27" cy="10" r="2"/><circle cx="27" cy="22" r="2"/><path d="M8 8l6-3M8 8l6 8M8 23l6-7M8 23l6 4M18 5l7 5M18 16l7-6M18 16l7 6M18 27l7-5"/>',
 train:'<path d="M5 24V5M5 24h22M9 10l5 7 5-3 7 7"/><path d="M21 21h5v-5"/>',
 eval:'<path d="M6 5h19v23H6zM10 11l2 2 4-4M10 21l2 2 4-4M19 11h3M19 21h3"/>',
 tune:'<path d="M5 8h22M5 16h22M5 24h22"/><circle cx="12" cy="8" r="3"/><circle cx="22" cy="16" r="3"/><circle cx="9" cy="24" r="3"/>'};
function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.model}</svg>`}
const stages=[
 {title:'准备数据',en:'DATA',icon:'data',sub:'模型从什么材料中学习？',detail:'先认识模型的“课本”：网页、代码和书籍如何变成训练材料。',lesson:'数据不是越多越好'},
 {title:'切分成 token',en:'TOKENIZATION',icon:'token',sub:'文字怎样变成数字？',detail:'文字先被切成片段，再映射到编号；token 不一定等于一个词。',lesson:'从文字到 token'},
 {title:'设计模型',en:'ARCHITECTURE',icon:'model',sub:'它用什么结构来学习？',detail:'参数是可以被调整的数字。网络结构决定这些数字如何共同处理输入。',lesson:'模型与参数'},
 {title:'开始预训练',en:'PRETRAINING',icon:'train',sub:'预测、比较、调整、重复',detail:'模型预测下一个 token，比较真实答案，再调整参数。这是我们的第一节图解课。',lesson:'下一词预测'},
 {title:'检查与评测',en:'EVALUATION',icon:'eval',sub:'学会了，还是记住了？',detail:'在没有用来训练的材料和任务上检查表现；评测贯穿整个开发过程。',lesson:'怎样知道模型学会了'},
 {title:'后训练与 RL',en:'POST-TRAINING',icon:'tune',sub:'让模型更会帮助人',detail:'用示范回答和任务反馈进一步训练模型。MiMo 为这一阶段提供了公开案例。',lesson:'从续写到助手'}
];
const scenes=[
 {title:'先把一句话，留出一个空。',sub:'训练样本 · 为了看清原理，先使用简化的 token 切分',caption:'这句话来自训练材料。模型只看到前面的 token，真正的下一个 token 被用作学习目标。'},
 {title:'模型给出的，是一组可能性。',sub:'预测 · 不是查找一个固定答案，而是输出概率分布',caption:'“蓝色”有 20% 的概率。图里只展示三个候选；真实模型会为整个词表的候选 token 计算概率。'},
 {title:'看一眼答案，衡量差距。',sub:'计算 loss · 真实答案得到的概率越低，损失越大',caption:'这条样本的真实下一个 token 是“蓝色”。交叉熵损失为 −ln(0.20) ≈ 1.61；它衡量这次预测的差距。'},
 {title:'调整参数，然后再来一次。',sub:'一次示意更新 · 预测 → 计算损失 → 更新参数',caption:'训练算法计算梯度并调整参数。这里把“蓝色”的概率示意性地提高到 42%；这不是任何真实模型的测量结果。'}
];
function href(page='home',extra=''){return `?variant=${state.variant}&page=${page}${extra}`}
function go(page){stopPlay();state.page=page;state.scene=0;state.quiz=null;updateUrl();render();window.scrollTo(0,0)}
function updateUrl(){history.replaceState(null,'',href(state.page))}
function header(){return `<header class="container topbar"><a class="brand" href="${href()}" data-go="home"><svg class="brand-mark" viewBox="0 0 40 43" fill="none"><path d="M4 9l16 7L36 9v25l-16 6-16-6zM20 16v24M9 3l11 5 11-5" stroke="currentColor" stroke-width="1.8"/></svg><div><div class="brand-title">Open Foundation<br>Model Training</div><div class="brand-sub">BY SOLO UNICORN</div></div></a><nav class="nav" aria-label="主导航"><a class="${['home','learn','lesson','next'].includes(state.page)?'active':''}" href="${href('learn')}" data-go="learn">开始学习</a><a class="${state.page==='projects'?'active':''}" href="${href('projects')}" data-go="projects">真实项目</a><a class="${state.page==='journal'?'active':''}" href="${href('journal')}" data-go="journal">图解与观察</a><a class="${state.page==='resources'?'active':''}" href="${href('resources')}" data-go="resources">学习资源 ↗</a></nav><div class="top-action"><span>中文 / EN</span><button class="small-button" data-go="lesson">我的第一课 <span aria-hidden="true">↗</span></button></div></header>`}
function footer(){return `<footer class="container footer"><span>Open Foundation Model Training · An educational project by Solo Unicorn</span><span>交互原型 · 教学模拟已标注 · ${state.completed?'本次已完成 1 课':'本次学习进度 0 / 6'}</span></footer>`}
function switcher(){const names={A:'探索地图',B:'视频课堂',C:'图解读物'};$('#switcher').innerHTML=`<div class="prototype-bar" role="group" aria-label="原型布局切换"><span class="proto-label">PROTOTYPE<br>入口布局</span><button class="arrow" data-cycle="-1" aria-label="上一个布局">←</button>${Object.entries(names).map(([key,name])=>`<button data-variant="${key}" class="${state.variant===key?'active':''}" aria-pressed="${state.variant===key}">${key} · ${name}</button>`).join('')}<button class="arrow" data-cycle="1" aria-label="下一个布局">→</button></div>`}
function neuralArt(color='#baceaa'){return `<svg viewBox="0 0 160 115" fill="none" aria-hidden="true">${[25,55,85].map(y=>[17,43,69,95].map(v=>`<path d="M25 ${y}L78 ${v}L135 55" stroke="${color}" stroke-opacity=".45"/>`).join('')).join('')}${[25,55,85].map(y=>`<circle cx="25" cy="${y}" r="5" fill="${color}"/>`).join('')}${[17,43,69,95].map(y=>`<circle cx="78" cy="${y}" r="6" fill="${color}"/>`).join('')}<circle cx="135" cy="55" r="9" fill="${color}"/></svg>`}
function flowArt(){return `<svg class="flow-svg" viewBox="0 0 460 266" role="img" aria-label="数据通过 token 和模型，得到预测；计算损失后反馈更新模型"><defs><marker id="arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0 0L5 2.5L0 5" fill="#869b75"/></marker></defs><text x="18" y="35" fill="#a5b997" font-size="9" letter-spacing="2">FROM RAW TEXT TO A LEARNING MODEL</text><g stroke="#789269" stroke-width="1" fill="none"><path d="M74 106H127M176 106H223M290 106H350" marker-end="url(#arrow)"/><path d="M380 142v40H256v-41" marker-end="url(#arrow)" stroke-dasharray="4 4"/></g><rect x="16" y="77" width="59" height="63" rx="5" fill="#304337" stroke="#617955"/><path d="M31 94h27M31 101h20M31 108h27M31 115h14M31 122h23" stroke="#a5ba8e"/><text x="29" y="161" font-size="10" fill="#c6d7b3">原始文本</text><rect x="127" y="89" width="50" height="33" rx="4" fill="#c0d19f"/><text x="135" y="109" font-size="10" fill="#2a3b2c">42  ·  8</text><text x="136" y="143" font-size="9" fill="#b8cca6">tokens</text><rect x="223" y="62" width="69" height="82" rx="7" fill="#304337" stroke="#7f9768"/><g stroke="#adc591" stroke-opacity=".7"><path d="M238 83L256 94 276 81M238 107L256 94 276 108M238 126L256 94M238 83L256 119 276 108M238 107L256 119 276 132"/></g><g fill="#c2dba3"><circle cx="238" cy="83" r="3"/><circle cx="238" cy="107" r="3"/><circle cx="238" cy="126" r="3"/><circle cx="256" cy="94" r="4"/><circle cx="256" cy="119" r="4"/><circle cx="276" cy="81" r="3"/><circle cx="276" cy="108" r="3"/><circle cx="276" cy="132" r="3"/></g><text x="237" y="161" font-size="10" fill="#c6d7b3">语言模型</text><rect x="350" y="77" width="77" height="65" rx="5" fill="#304337" stroke="#617955"/><rect x="363" y="90" width="48" height="6" rx="2" fill="#d7bd91"/><rect x="363" y="103" width="31" height="6" rx="2" fill="#a1b98a"/><rect x="363" y="116" width="16" height="6" rx="2" fill="#75906b"/><text x="366" y="161" font-size="10" fill="#c6d7b3">预测概率</text><text x="301" y="200" font-size="9" fill="#afc49b">计算差距，更新参数</text><circle class="particle" cx="82" cy="106" r="3" fill="#e3ca97"/><g transform="translate(19 208)"><path d="M0 33h155M0 0v33" stroke="#627956"/><path d="M4 2C18 5 20 16 35 20S65 28 90 29 125 30 150 31" fill="none" stroke="#b2ca93" stroke-width="1.7"/><text x="173" y="16" font-size="10" fill="#c6d7b3">一次次预测，一点点学会。</text><text x="173" y="33" font-size="8" fill="#849c77">概念示意 · 非真实训练曲线</text></g></svg>`}
function board(){return `<div class="board"><div class="board-lines"></div><div class="board-head"><span><i class="live-dot"></i> INSIDE THE TRAINING LOOP</span><span>01 / 06</span></div>${flowArt()}<div class="board-footer"><span>从一个句子开始，理解一整个过程。</span><button data-action="board-pause" aria-label="暂停示意动画">Ⅱ</button></div></div>`}
function sectionHead(kicker,title,description='',action=''){return `<div class="section-head"><div>${kicker?`<div class="section-kicker">${kicker}</div>`:''}<h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${action}</div>`}
function mapSection(){return `<section class="section" id="map">${sectionHead('01 / The big picture','先有一张地图，再走好每一步。','点一个阶段，看看它在整个训练过程中的位置。',`<span class="badge">入门路线 · 约 30 分钟</span>`)}<div class="route-map">${stages.map((s,i)=>`<button class="stage ${state.stage===i?'selected':''}" data-stage="${i}" aria-pressed="${state.stage===i}"><span class="stage-num">0${i+1}<span>${i<5?'→':'↗'}</span></span>${icon(s.icon,'stage-icon')}<h3>${s.title}</h3><p>${s.sub}</p></button>`).join('')}</div><div class="support-rail">评测贯穿全程 · 算力、存档与恢复支撑每一阶段</div><div id="stage-detail">${stageDetail()}</div></section>`}
function stageDetail(){const s=stages[state.stage];return `<div class="stage-detail"><p><strong>0${state.stage+1} / ${s.title}</strong>${s.detail}</p><button class="text-button" data-action="stage-open">${state.stage===3?'打开示范课':'看图理解这个阶段'} <span>↗</span></button></div>`}
function projectCards(){return `<div class="projects"><a class="project-card" href="${href('marin')}" data-go="marin"><div><span class="badge green">案例 A · 预训练与训练系统</span><h3>Marin <span style="font-size:15px;color:#83916f">↗</span></h3><p>从数据走向模型，观察真实训练中的实验、决策和故障恢复。</p><div class="bottom"><span>Open development</span><span>·</span><span>从这里认识 pretraining →</span></div></div><div class="project-art">${neuralArt('#8b9f70')}</div></a><a class="project-card" href="${href('mimo')}" data-go="mimo"><div><span class="badge orange-text">案例 B · 后训练与强化学习</span><h3>Xiaomi MiMo <span style="font-size:15px;color:#c09b7b">↗</span></h3><p>模型如何从任务和反馈中继续学习？从 RL 看懂另一半过程。</p><div class="bottom" style="color:#a27754"><span>Post-training</span><span>·</span><span>从这里认识 reinforcement learning →</span></div></div><div class="project-art"><svg viewBox="0 0 150 115" fill="none" aria-hidden="true"><path d="M42 35C75 7 120 18 121 51M113 86C82 112 34 96 29 62" stroke="#c4a889" stroke-width="1.5"/><path d="M116 44l5 8 6-8M24 69l5-8 7 6" stroke="#c4a889"/><rect x="12" y="35" width="44" height="30" rx="5" fill="#f2e5d5" stroke="#ceb398"/><rect x="95" y="57" width="44" height="30" rx="5" fill="#eee4d3" stroke="#ceb398"/><text x="23" y="54" fill="#977859" font-size="10">尝试</text><text x="106" y="76" fill="#977859" font-size="10">反馈</text></svg></div></a></div>`}
function resourceRows(){return `<div class="resource-list"><button class="resource" data-action="video" style="text-align:left;background:none;border-left:0;border-right:0;border-top:0;padding-left:0"><span class="resource-art">${neuralArt()}<span class="play-small">▶</span></span><span><h3>跟着 Karpathy，认识 LLM 的完整过程</h3><p>视频导读 · 英文 · 可选深入观看</p></span><span class="muted" style="margin-left:auto">↗</span></button><a class="resource" href="https://www.3blue1brown.com/lessons/gpt/" target="_blank" rel="noopener noreferrer"><span class="resource-art" style="background:#ede6d9">${neuralArt('#8b826b')}</span><span><h3>3Blue1Brown：把 Transformer 画给你看</h3><p>原作者图解与视频 · 英文 · 模型结构</p></span><span class="muted" style="margin-left:auto">↗</span></a></div>`}
function VariantA(){return `<main class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow">A VISUAL FIELD GUIDE TO MODEL TRAINING</div><h1>从数据到智能，<br><em>看懂训练的每一步。</em></h1><p>不用先读懂论文。跟着图解、交互实验和真实项目，<br>一步一步，建立你的模型训练全局观。</p><div class="actions"><button class="button primary" data-go="lesson">开始我的第一课 <span>↗</span></button><a class="text-button" href="#map">先看全流程 <span>↓</span></a></div><div class="hero-note"><span><b>✓</b> 无需训练背景</span><span><b>✓</b> 图解 + 动手探索</span><span><b>✓</b> 关键结论附来源</span></div></div>${board()}</section>${mapSection()}<section class="section">${sectionHead('02 / Learn from real projects','把知识，放回真实现场。','同一张训练地图，两种不同阶段的观察窗口。',`<button class="text-button" data-go="projects">探索项目 ↗</button>`)}${projectCards()}</section><section class="section split"><div>${sectionHead('03 / See it explained','有些知识，看一遍更明白。')}${resourceRows()}</div><div>${sectionHead('Your first small win','今天，只需要学懂一件事。')}<div class="callout"><span class="large-serif">01</span><div><h3>模型怎么从“猜错”<br>走到“猜得更好”？</h3><p>一段图解 · 一个实验 · 一道小题</p><button class="text-button" data-go="lesson">进入 8 分钟示范课 →</button></div></div></div></section></main>`}
function VariantB(){return `<main class="container"><div class="studio-heading"><div><div class="eyebrow">THE VISUAL CLASSROOM</div><h1>先看见，再理解。</h1><p>按自己的节奏，用一段图解和一次尝试，学懂模型训练。</p></div><span class="badge">零背景入门 · 学习状态保留在本次会话</span></div><section class="studio">${player()}<div class="playlist"><div class="playlist-head">你的第一条学习路线 <span class="muted">/ 6 个单元</span></div>${stages.map((s,i)=>`<button class="playlist-item ${i===3?'active':''}" data-stage-modal="${i}" style="width:100%;text-align:left;border-left:0;border-right:0;border-top:0"><b>0${i+1}</b><div><h3>${s.title}</h3><p>${s.sub}</p></div><span>${i===3?'▶':'↗'}</span></button>`).join('')}</div></section><div class="studio-banner"><div><h3>看完之后，试着亲手改变它。</h3><p>进入完整课程，调整学习率，看预测和 loss 怎样变化。</p></div><button class="button primary" data-go="lesson">打开互动课堂 ↗</button></div><section class="section split"><div>${sectionHead('Watch with a question','补一块你需要的知识。')}${resourceRows()}</div><div>${sectionHead('Back to the field','这和真实训练有什么关系？')}<div class="callout"><span class="large-serif">M</span><div><h3>从一次预测，<br>走进 Marin 的训练。</h3><p>理解概念之后，回到真实案例。</p><button class="text-button" data-go="marin">打开案例导读 →</button></div></div></div></section></main>`}
function VariantC(){return `<main class="container"><section class="magazine-mast"><div><div class="eyebrow">AN ILLUSTRATED LEARNING JOURNAL</div><h1>Inside the learning.</h1><p>打开模型训练的过程，也打开理解它的另一种方式。</p></div><span class="mono">VOL. 01<br>从零开始理解训练</span></section><section class="magazine-feature"><div class="magazine-visual"><svg viewBox="0 0 560 300" role="img" aria-label="文本输入通过神经网络形成预测"><g transform="translate(15 70)"><rect width="112" height="143" rx="5" fill="#f8f8ee" stroke="#9ca68c"/><path d="M20 25h70M20 38h58M20 51h65M20 64h45M20 90h70M20 103h40M20 116h61" stroke="#a4ae96" stroke-width="2"/></g><path d="M143 142h38M384 142h30" stroke="#697e50" stroke-width="2"/><g transform="translate(180 35) scale(1.45)">${neuralArt('#718956').replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g transform="translate(427 93)"><rect width="118" height="103" rx="6" fill="#314537"/><rect x="16" y="21" width="83" height="9" rx="2" fill="#d8c19d"/><rect x="16" y="46" width="56" height="9" rx="2" fill="#c2d4a6"/><rect x="16" y="71" width="25" height="9" rx="2" fill="#7c956b"/></g><text x="16" y="264" fill="#657957" font-family="Georgia" font-size="12" font-style="italic">Text → Tokens → Prediction → Learning</text><text x="437" y="264" fill="#657957" font-size="9">概念插画</text></svg></div><div class="magazine-copy"><span class="badge green" style="align-self:start">第一篇 · 可交互图解</span><h2>模型是怎么<br>从一次“猜错”<br>开始学习的？</h2><p>从“天空是……”这个句子出发，看懂预测、损失与参数更新。不需要公式基础。</p><button class="text-button" data-go="lesson" style="margin-top:23px">阅读并动手试试 · 约 8 分钟 ↗</button></div></section><section>${[['从原始数据到一个有用的助手','一张可探索的地图，串起训练的不同阶段。','learn','全景导读'],['Marin：打开预训练的现场','从公开代码、实验记录和决策中学习。','marin','真实案例'],['MiMo：模型怎样从反馈中继续学习','带着问题认识 rollout、reward 和 RL。','mimo','真实案例']].map((a,i)=>`<a class="editorial-row" data-go="${a[2]}" href="${href(a[2])}"><span class="index">0${i+2}</span><div><h3>${a[0]}</h3><p>${a[1]}</p></div><span class="type">${a[3]} ↗</span></a>`).join('')}</section><section class="section split" style="margin-top:35px"><div>${sectionHead('A second perspective','换个角度，看得更清楚。')}${resourceRows()}</div><div class="callout"><div><div class="eyebrow">MADE TO BE SHARED</div><h3 style="margin-top:17px">把你刚理解的东西，<br>分享给下一个好奇的人。</h3><p>每篇文章都有专属图卡与分享摘要。</p><button class="text-button" data-action="share">预览第一课的分享卡 ↗</button></div></div></section></main>`}
function player(){const s=scenes[state.scene],probs=state.scene===3?[42,35,23]:[20,45,35];return `<div class="lesson-player"><div class="player-top"><span>交互图解 / THE TRAINING LOOP</span><span class="badge">教学模拟 · 无音频</span></div><div class="player-center"><h3>${s.title}</h3><p class="player-subtitle">${s.sub}</p><div class="token-row"><button class="token" data-token="天空">天空</button><button class="token" data-token="是">是</button><button class="token answer" data-token="目标">${state.scene>1?'蓝色':'?'}</button><span style="font-size:11px;color:#90a57d;margin-left:9px">→</span><span style="font-size:11px;color:#bad0a5;margin-left:5px">下一个 token</span></div><div class="prediction-bars" style="opacity:${state.scene===0?'.25':'1'}">${['蓝色','灰色','晴朗'].map((w,i)=>`<div class="prob ${i===0?'correct':''}"><span>${w}</span><div class="track"><i style="width:${probs[i]}%"></i></div><b>${probs[i]}%</b></div>`).join('')}</div></div><p class="player-caption" id="scene-caption">${s.caption}</p><div class="player-controls"><button class="play-round" data-action="play" aria-label="${state.playing?'暂停':'播放'}分镜">${state.playing?'Ⅱ':'▶'}</button><div class="scene-dots">${['输入','预测','比较','调整'].map((n,i)=>`<button data-scene="${i}" class="${state.scene===i?'active':''}" aria-pressed="${state.scene===i}">${i+1} ${n}</button>`).join('')}</div><span class="player-count">${state.scene+1} / 4</span><button class="text-button" data-action="next-scene" style="color:#bacaac;font-size:15px" aria-label="下一分镜">→</button></div></div>`}
function sidebar(){return `<aside class="lesson-sidebar"><div class="eyebrow">YOUR FIRST LEARNING PATH</div><h3>从零看懂<br>模型训练</h3><ol class="chapter-list">${[['先看全流程','learn'],['文字如何变成 token','token'],['模型怎样学习','lesson'],['亲手调整学习率','#experiment'],['回到真实项目','#case'],['检查我的理解','#quiz']].map(([t,p],i)=>`<li><button ${p[0]==='#'?`data-anchor="${p}"`:p==='token'?'data-stage-modal="1"':`data-go="${p}"`} class="${i===2?'active':''}"><span>${i===5&&state.completed?'✓':String(i+1).padStart(2,'0')}</span>${t}</button></li>`).join('')}</ol><div class="progress-track"><i style="width:${state.completed?16.7:0}%"></i></div><p class="mono muted">${state.completed?'1':'0'} / 6 UNITS COMPLETED</p><div class="sidebar-note">不必一次学完所有术语。<br>遇到不熟悉的概念，<br>点开补一小块知识就好。<button class="text-button" data-go="resources" style="margin-top:10px">我的知识补给站 ↗</button></div></aside>`}
function lesson(){return `<main class="container"><div class="crumb"><button data-go="home">首页</button> / <button data-go="learn">从零看懂模型训练</button> / 模型怎样学习</div><div class="lesson-grid">${sidebar()}<article><div class="mobile-progress">从零看懂训练 · ${state.completed?'已完成 1 课':'开始你的第一课'}</div><div class="eyebrow">LESSON 01 / PRETRAINING, EXPLAINED VISUALLY</div><h1 class="lesson-title">模型，究竟是怎么学会<br>预测下一个词的？</h1><p class="lesson-lead">从一句“天空是……”开始。先看它怎样猜，再亲手改变它的学习过程。你不需要任何模型训练背景。</p><div class="lesson-meta"><span>Solo Unicorn 编辑</span><span>约 8 分钟</span><span class="badge green">入门 · 无需代码</span><button class="share-button" data-action="share">↗ 分享这一课</button></div><div id="player-host">${player()}</div><div class="takeaway"><strong>先带走一个直觉：</strong>训练把真实文本的下一个 token 当作答案，通过反复预测、比较和调整，让模型逐渐学会文本中的规律。</div><section class="lesson-block"><div class="block-head"><span class="block-number">01</span><h2>先看懂这四步，就够了。</h2></div><p>上面的每个片段都可以点开。点击「播放」自动走一遍，或按自己的节奏切换输入、预测、比较与调整。这里把中文切分简化了；真实 tokenizer 可能把同一句话切成不同片段。</p><details><summary>补一块知识：token、参数和 loss 分别是什么？</summary><p><strong>Token</strong> 是模型处理文字的基本片段，不一定是完整的词。<strong>参数</strong> 是训练过程中会调整的数字。<strong>Loss</strong> 是用来衡量预测差距的数值，它通过梯度影响参数如何更新。</p><a class="source-link" href="https://www.3blue1brown.com/lessons/gpt/" target="_blank" rel="noopener noreferrer">用 3Blue1Brown 的图解进一步理解 ↗</a></details></section><section class="lesson-block" id="experiment"><div class="block-head"><span class="block-number">02</span><h2>换你来：如果每次多调整一点？</h2></div><p>拖动学习率，观察同一个三候选小模型训练 24 次后的变化。学习率控制每次参数更新的幅度。</p><div class="experiment"><div><span class="badge">可交互 · 玩具 softmax 模型</span><h3 style="margin-top:16px">每一步，调整多大？</h3><p>只训练同一句话，目标始终是“蓝色”。<br>拖动后自动重新计算。</p><label class="slider-label" for="lr">学习率 <output id="lr-value">0.20</output></label><input type="range" id="lr" min="0.02" max="1.20" step="0.02" value="${state.learningRate}" aria-label="学习率"><div class="range-labels"><span>小步调整</span><span>大步调整</span></div><div class="stat-mini"><span>目标概率 <strong id="prob-result"></strong></span><span>Loss <strong id="loss-result"></strong></span></div></div><div><div id="loss-chart"></div><div class="chart-caption"><span>你的学习率</span><span>固定对照 0.08</span></div></div></div><p style="font-size:10px;margin-top:12px">教学边界：这里只更新三个 logits，损失是 −ln P(蓝色)，不代表 Transformer 或真实训练效果。记住一个句子，也不等于学会语言；大模型中学习率越大并不一定越好。</p></section><section class="lesson-block" id="case"><div class="block-head"><span class="block-number">03</span><h2>把这个直觉，带到 Marin。</h2></div><p>真实训练会把大量 token 分成批次，在许多设备上反复执行类似的学习循环。它还需要同时解决数据质量、计算效率、评测和故障恢复。</p><div class="case-note"><div>${icon('train')}</div><div><h3>看到训练曲线时，先问两个问题。</h3><p>第一，模型在训练样本上的预测是否改善？第二，在没有参与训练的材料上，表现也改善了吗？仅凭 train loss 下降，还不能判断模型的所有能力。</p><a href="https://github.com/marin-community/marin" target="_blank" rel="noopener noreferrer">一手资料：Marin 公开训练项目 ↗</a><button class="text-button" data-go="marin" style="display:block">查看本站的 Marin 案例导读 →</button></div></div></section><section class="lesson-block" id="quiz"><div class="block-head"><span class="block-number">04</span><h2>用一个小问题，检查你的理解。</h2></div><div class="quiz"><p>模型在训练中“学习”，最关键的变化是什么？</p><div class="quiz-options">${[['A','把所有训练句子存进一个可查找的数据库'],['B','根据预测误差，调整模型的参数'],['C','每次回答之前，都由人告诉它正确答案']].map(([key,t])=>`<button data-answer="${key}"><span>${key}</span>${t}</button>`).join('')}</div><div class="quiz-feedback" id="quiz-feedback" aria-live="polite">选一个答案，看具体解释。</div></div></section><section class="lesson-block"><div class="block-head"><span class="block-number">05</span><h2>想再看一遍？换一位老师。</h2></div><p>带着这个问题去看：一段互联网文本，经过哪些步骤才能改变模型的参数？这是可选补充，不用看完整部视频才能继续。</p><div class="video-card"><button class="video-cover" data-action="video" aria-label="打开 Karpathy 视频">${neuralArt()}<span class="big-play">▶</span></button><div class="video-info"><span class="badge">原作者视频 · 英文</span><h3>Deep Dive into LLMs like ChatGPT</h3><p>Andrej Karpathy · 面向普通观众的完整讲解</p><p style="margin-top:6px">重点关注 tokenization 与 pretraining；通过原视频章节选择观看。</p><button class="text-button" data-action="video">打开视频与观看导读 ↗</button></div></div><a class="source-link" href="https://www.3blue1brown.com/lessons/gpt/" target="_blank" rel="noopener noreferrer" style="margin-top:12px">还想看更多图片？阅读 3Blue1Brown 的 Transformer 图解 ↗</a></section><section class="lesson-block" style="padding-top:23px;padding-bottom:23px"><span class="eyebrow">NOTES & SOURCES</span><a class="source-link" href="https://www.3blue1brown.com/lessons/gpt/" target="_blank" rel="noopener noreferrer">01 · 3Blue1Brown — Transformers, the tech behind LLMs</a><a class="source-link" href="https://github.com/marin-community/marin" target="_blank" rel="noopener noreferrer">02 · Marin — 开发过程、训练与评测</a><p style="font-size:10px;color:var(--muted)">本页为原创教学原型。所有交互数据均为教学模拟，外部视频由原作者提供。</p></section><div class="next-lesson"><div><p id="completion-text">${state.completed?'✓ 已完成理解检查':'看懂之后，接着问一个问题'}</p><h3>为什么“学会续写”还不等于“会当助手”？</h3></div><button class="button primary" data-go="next">下一课 →</button></div></article></div></main>`}
function train(rate){let logits=[Math.log(.2),Math.log(.45),Math.log(.35)],losses=[];let prob;for(let step=0;step<=24;step++){const ex=logits.map(Math.exp),sum=ex.reduce((a,b)=>a+b,0),p=ex.map(v=>v/sum);prob=p[0];losses.push(-Math.log(prob));logits=logits.map((v,i)=>v-rate*(p[i]-(i===0?1:0)))}return {losses,prob}}
function updateChart(){if(!$('#loss-chart'))return;const result=train(state.learningRate),control=train(.08);const line=a=>a.map((v,i)=>`${28+i*11},${145-v/1.7*114}`).join(' ');$('#loss-chart').innerHTML=`<svg viewBox="0 0 315 185" role="img" aria-label="玩具模型交叉熵损失随训练步数下降的模拟曲线"><text x="28" y="13" font-size="9" fill="#8b947f">交叉熵 LOSS</text>${[0,.5,1,1.5].map(v=>`<line x1="27" x2="293" y1="${145-v/1.7*114}" y2="${145-v/1.7*114}" stroke="#e5e8dd"/><text x="1" y="${148-v/1.7*114}" fill="#919986" font-size="8">${v.toFixed(1)}</text>`).join('')}<polyline points="${line(control.losses)}" stroke="#bcbeb0" stroke-width="1.5" stroke-dasharray="4 4" fill="none"/><polyline points="${line(result.losses)}" stroke="#4b714b" stroke-width="2.4" fill="none"/><circle cx="292" cy="${145-result.losses[24]/1.7*114}" r="3.5" fill="#4b714b"/><text x="25" y="164" fill="#8b947f" font-size="9">0</text><text x="155" y="164" fill="#8b947f" font-size="9">12</text><text x="269" y="164" fill="#8b947f" font-size="9">24 步</text></svg>`;$('#lr-value').textContent=state.learningRate.toFixed(2);$('#prob-result').textContent=Math.round(result.prob*100)+'%';$('#loss-result').textContent=result.losses[24].toFixed(2)}
function learn(){return `<main class="container"><section class="source-section"><div class="eyebrow">START WITH THE BIG PICTURE</div><h1>不用先成为专家，就可以开始。</h1><p>先看清模型训练的全貌，再学会解释其中一小步。下方地图可以逐个探索；原型中已经完整实现「模型怎样学习」这一课。</p></section>${mapSection()}<section class="section">${sectionHead('Choose your pace','今天，你想走多远？')}<div class="card-grid"><div class="learn-card"><span class="badge green">建议从这里开始</span><h3>8 分钟 · 学懂一个循环</h3><p>预测、损失、调整参数。完整图解、可操作实验与理解检查。</p><button class="text-button" data-go="lesson">进入已完成示范课 →</button></div><div class="learn-card"><span class="badge">原型路线预览</span><h3>30 分钟 · 建立全局观</h3><p>从数据到后训练，六个短单元逐步补齐你的训练地图。</p><button class="text-button" data-stage-modal="0">预览第一阶段 →</button></div><div class="learn-card"><span class="badge">案例阅读</span><h3>跟着一个真实项目学习</h3><p>把刚学到的概念，带入 Marin 的预训练或 MiMo 的 RL。</p><button class="text-button" data-go="projects">选择一个项目 →</button></div></div></section></main>`}
function projects(){return `<main class="container"><section class="source-section"><div class="eyebrow">LEARN FROM THE OPEN PROCESS</div><h1>知识有了坐标，项目就能看懂。</h1><p>先选择你想理解的阶段。下面是案例导读，不是当前运行状态看板；实时数据以原始来源为准。</p></section>${projectCards()}<section class="section" style="margin-top:35px">${sectionHead('A shared map','两个窗口，连接训练的前后阶段。')}<div class="callout"><div><h3>Marin 帮你认识从数据中学习。<br>MiMo 帮你认识从任务反馈中学习。</h3><p>不同项目公开范围不同。每个案例都说明能观察到什么、还不能确认什么。</p><button class="text-button" data-go="learn">回到训练全流程 →</button></div></div></section></main>`}
function project(kind){const marin=kind==='marin';const items=marin?[['研究与配方','为什么先用小实验验证大规模训练的选择？','理解扩展实验如何帮助研究者作出更有依据的决定。'],['数据与预训练','大量文本，如何进入同一个学习循环？','把 token、batch、loss 等概念放回训练过程，逐步理解它们的关系。'],['系统与恢复','训练为什么会停？又怎样继续？','了解 checkpoint、设备故障与恢复如何影响真正完成训练的时间。']]:[['从基础模型出发','模型已经会续写，为什么还需要后训练？','区分一般的语言预测能力、遵循指令和完成任务的能力。'],['与任务环境交互','一次 rollout 是怎样产生的？','模型尝试完成任务，得到一条由动作与反馈组成的轨迹。'],['反馈与参数更新','reward 如何影响后续行为？','理解训练目标与评测表现的差别，以及奖励设计为什么重要。']];return `<main class="container"><div class="crumb"><button data-go="projects">真实项目</button> / ${marin?'Marin':'Xiaomi MiMo'}</div><section class="project-hero"><div class="eyebrow">CASE STUDY / ${marin?'PRETRAINING':'POST-TRAINING & RL'}</div><h1>${marin?'Marin':'Xiaomi MiMo'}</h1><p>${marin?'把一个模型如何被训练的过程，变成可以观察和理解的公开案例。先理解主线，再深入代码、实验和日志。':'从任务、轨迹与奖励出发，理解模型在预训练之后如何继续学习。MiMo-V2.6 的 RL 与 MiMo-7B 的历史配方分别阅读。'}</p><div style="margin-top:20px"><span class="badge">案例导读原型</span><span class="badge green">${marin?'公开开发过程':'公开后训练资料'}</span><span class="badge">非实时快照</span></div></section><div class="project-layout"><div>${items.map(([k,t,d],i)=>`<div class="timeline-item"><span class="badge">0${i+1} / ${k}</span><h3>${t}</h3><p>${d}</p><button class="text-button" ${i===1&&marin?'data-go="lesson"':`data-stage-modal="${marin?[2,3,4][i]:5}"`}>${i===1&&marin?'用第一课补齐直觉':'打开概念导读'} →</button></div>`).join('')}</div><aside class="project-aside"><h3>带着问题看一手资料</h3><p>先问“这个变化属于哪个训练阶段”，再看指标。分清计划、实验结果与真正部署。</p><a class="source-link" href="${marin?'https://github.com/marin-community/marin':'https://mimo.mi.com/docs/en-US/news/latest/v2-6'}" target="_blank" rel="noopener noreferrer">${marin?'Marin GitHub':'MiMo-V2.6 官方说明'} ↗</a><a class="source-link" href="${marin?'https://github.com/marin-community/marin/issues/8435':'https://github.com/XiaomiMiMo/MiMo'}" target="_blank" rel="noopener noreferrer">${marin?'Hero Run 原始讨论':'MiMo-7B 历史技术资料'} ↗</a><a class="source-link" href="${marin?'https://mtracker.oa.dev/hero-run-535b':'https://mimo.xiaomi.com/rl/'}" target="_blank" rel="noopener noreferrer">${marin?'Marin Tracker（AI 汇总，需溯源）':'MiMo RL dashboard'} ↗</a></aside></div></main>`}
function journal(){return `<main class="container"><section class="source-section"><div class="eyebrow">ILLUSTRATED NOTES</div><h1>一个问题，一次看懂。</h1><p>每篇内容都能独立阅读、操作和分享，也能带你回到整个训练过程。</p></section><div class="magazine-feature"><div class="magazine-visual">${neuralArt('#77905c')}</div><div class="magazine-copy"><span class="badge green" style="align-self:start">可阅读 · 可操作 · 可分享</span><h2>模型怎样从<br>“猜错”中学习？</h2><p>用四段动画、一个玩具模型和一道检查题，理解训练的基本循环。</p><button class="text-button" data-go="lesson" style="margin-top:20px">打开第一篇图解 ↗</button><button class="text-button" data-action="share">看看分享出去是什么样 ↗</button></div></div></main>`}
function resources(){return `<main class="container"><section class="source-section"><div class="eyebrow">YOUR KNOWLEDGE SUPPLY STATION</div><h1>缺哪块知识，就补哪一块。</h1><p>每份资源都有一个明确的问题和返回路径。外部视频保留原作者署名；本站图解帮助你先建立直觉。</p></section>${[['我想理解完整训练过程','Andrej Karpathy · Deep Dive into LLMs like ChatGPT','面向普通观众的完整讲解。先找 tokenization 和 pretraining 章节，带着“文本怎样改变参数”这个问题看。','https://www.youtube.com/watch?v=7xTGNNLPyMI'],['我想看懂模型内部结构','3Blue1Brown · Transformers','用图像理解 token、向量和网络处理；已经理解基本训练循环后，再来补架构知识。','https://www.3blue1brown.com/lessons/gpt/'],['我不懂什么是神经网络','3Blue1Brown · Neural Networks','从更基础的神经网络直觉开始。它是可选补充，无需全部学完才能阅读本站第一课。','https://www.3blue1brown.com/lessons/neural-networks/'],['我想看真实的公开实现','Marin · 官方项目','连接数据准备、训练、评测与开发记录。先阅读 README 的项目说明，再按自己的问题深入。','https://github.com/marin-community/marin']].map(([q,t,d,u])=>`<div class="source-card"><div><span class="eyebrow" style="font-size:8px">${q}</span><h3 style="margin-top:10px">${t}</h3></div><p>${d}</p><a href="${u}" target="_blank" rel="noopener noreferrer" aria-label="打开 ${t}">↗</a></div>`).join('')}<div class="callout" style="margin:30px 0"><div><h3>补好这一块，就回到你的学习主线。</h3><button class="text-button" data-go="lesson">回到「模型怎样学习」 →</button></div></div></main>`}
function nextLesson(){return `<main class="container"><div class="crumb"><button data-go="lesson">上一课</button> / 从续写到助手</div><section class="source-section"><div class="eyebrow">LESSON 02 / A SHORT PREVIEW</div><h1>会续写，还不等于会当助手。</h1><p>预训练学习文本规律；后训练进一步塑造回答方式和任务表现。这一页是下一课的结构预览。</p></section><div class="card-grid">${[['01','预训练','阅读大量文本，学习预测下一个 token。','train'],['02','监督微调 · SFT','通过示范回答，学习怎样回应用户请求。','data'],['03','强化学习 · RL','尝试任务，利用奖励信号调整模型行为。','tune']].map(([n,t,d,i])=>`<div class="learn-card"><span class="mono muted">${n}</span>${icon(i,'stage-icon')}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div><div class="callout" style="margin:30px 0"><div><h3>想象同一个问题：“帮我解释什么是重力。”</h3><p>训练阶段不同，模型的回答方式可能不同。完整课程将展示可切换的回答示例与反馈过程。</p><button class="text-button" data-go="mimo">现在先去 MiMo 案例了解后训练 →</button></div></div></main>`}
function render(){const content={home:()=>({A:VariantA,B:VariantB,C:VariantC}[state.variant]()),lesson,learn,projects,marin:()=>project('marin'),mimo:()=>project('mimo'),journal,resources,next:nextLesson};$('#app').innerHTML=header()+(content[state.page]||content.home)()+footer();switcher();updateChart();document.title=(state.page==='lesson'?'模型怎样学习 · ':state.page==='resources'?'知识补给站 · ':'')+'Open Foundation Model Training';}
function refreshPlayer(){const el=$('.lesson-player');if(el)el.outerHTML=player()}
function stopPlay(){clearInterval(playTimer);playTimer=null;state.playing=false}
function setScene(n){state.scene=n;refreshPlayer()}
function play(){if(state.playing){stopPlay();refreshPlayer();return}if(state.scene===3)state.scene=0;state.playing=true;refreshPlayer();playTimer=setInterval(()=>{if(state.scene>=3){stopPlay();refreshPlayer()}else setScene(state.scene+1)},3800)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2300)}
function modal(body){modalReturn=document.activeElement;stopPlay();$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${body.includes('分享')?'分享预览':'学习补充'}"><button class="close-modal" data-action="close" aria-label="关闭">×</button>${body}</section></div>`;document.body.style.overflow='hidden';$('.close-modal').focus()}
function closeModal(){$('#overlay').innerHTML='';document.body.style.overflow='';modalReturn?.focus();refreshPlayer()}
function stageModal(i){if(i===3){closeModal();go('lesson');return}const s=stages[i];modal(`<div class="eyebrow">阶段 0${i+1} / ${s.en}</div><h2 style="margin-top:15px">${s.title}：${s.sub}</h2><p>${s.detail}</p><div class="callout" style="margin:18px 0"><div style="width:45px;flex-shrink:0">${icon(s.icon)}</div><div><h3 style="font-size:17px">${s.lesson}</h3><p>这是阶段导读预览。当前已完成的互动课程从「下一词预测」开始，你可以先学会这一小步，再返回全局。</p></div></div><div class="modal-actions"><button class="button primary" data-action="start-lesson">进入完整示范课 →</button><button class="button" data-action="resources">查看补充资源 ↗</button></div>`)}
function shareModal(){modal(`<div class="eyebrow">SHARE WHAT YOU UNDERSTAND</div><h2 style="margin-top:12px">学懂一件事，也分享一个入口。</h2><p>分享这一课的链接、介绍和图卡。</p><div class="share-cover"><div class="brandline">OPEN FOUNDATION MODEL TRAINING</div><h3>模型怎样从<br>一次“猜错”中学习？</h3><div class="share-bottom"><span>预测 → 比较 → 调整 → 再试一次</span><span>by Solo Unicorn ↗</span></div></div><div class="share-info"><h3>一节可交互的模型训练入门课</h3><p>用图解和亲手操作，理解下一词预测、loss 与参数更新。</p></div><div class="draft">模型在训练时，到底改变了什么？<br>我把预测、比较和参数更新做成了一节可以亲手操作的图解课。无需训练背景，调整学习率就能看到变化。<br>这是 Open Foundation Model Training 的第一课，by Solo Unicorn。</div><div class="modal-actions"><button class="button primary" data-action="copy-draft">复制分享文案</button><button class="button" data-action="download">下载 1200 × 630 图卡</button><button class="button" data-action="copy-link">复制课程链接</button></div><p class="modal-note">复制链接或下载图卡后，可以自行分享给朋友。此操作不会自动发布到社交账号。</p>`)}
function videoModal(){modal(`<div class="eyebrow">WATCH WITH A QUESTION</div><h2 style="margin-top:12px">从文本，到一次参数更新。</h2><p>Andrej Karpathy · Deep Dive into LLMs like ChatGPT · 原作者视频</p><iframe src="https://www.youtube-nocookie.com/embed/7xTGNNLPyMI" title="Andrej Karpathy — Deep Dive into LLMs like ChatGPT" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><div class="takeaway"><strong>带着问题看：</strong>文本怎样变成 token？预测结果怎样转化为训练信号？<br>建议用原视频章节寻找 tokenization 和 pretraining；无需一次看完。</div><a class="text-button" href="https://www.youtube.com/watch?v=7xTGNNLPyMI" target="_blank" rel="noopener noreferrer" style="margin-top:14px">如果播放器不可用，在 YouTube 打开原视频 ↗</a><p class="modal-note">嵌入播放取决于网络和原视频设置。本站不托管或剪辑原作者视频，未提供未经核验的精确片段时间戳。</p>`)}
function downloadCover(){const c=document.createElement('canvas');c.width=1200;c.height=630;const x=c.getContext('2d');x.fillStyle='#25352e';x.fillRect(0,0,1200,630);x.fillStyle='#bfd0a8';x.font='18px sans-serif';x.fillText('OPEN FOUNDATION MODEL TRAINING',68,72);x.fillStyle='#e8efd9';x.font='600 64px sans-serif';x.fillText('模型怎样从',68,234);x.fillText('一次“猜错”中学习？',68,326);x.fillStyle='#b9cba3';x.font='23px sans-serif';x.fillText('预测 → 比较 → 调整 → 再试一次',68,550);x.font='20px sans-serif';x.fillText('by Solo Unicorn',944,550);x.strokeStyle='#718665';x.lineWidth=2;[[865,156,1025,250],[865,250,1025,250],[865,344,1025,250]].forEach(a=>{x.beginPath();x.moveTo(a[0],a[1]);x.lineTo(a[2],a[3]);x.stroke()});[[865,156],[865,250],[865,344],[1025,250]].forEach(([a,b])=>{x.fillStyle='#b9cba3';x.beginPath();x.arc(a,b,10,0,Math.PI*2);x.fill()});c.toBlob(blob=>{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='model-training-first-lesson-1200x630.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('分享图卡已生成')},'image/png')}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制')}catch{modal(`<h2>复制以下内容</h2><textarea style="width:100%;height:190px;margin-top:20px">${text.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</textarea>`);$('textarea').select()}}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(e.target.classList.contains('modal-backdrop')){closeModal();return}if(!el)return;
 if(el.dataset.go){e.preventDefault();go(el.dataset.go)}
 else if(el.dataset.variant){state.variant=el.dataset.variant;state.page='home';stopPlay();updateUrl();render();window.scrollTo(0,0)}
 else if(el.dataset.cycle){const a=['A','B','C'];state.variant=a[(a.indexOf(state.variant)+Number(el.dataset.cycle)+3)%3];state.page='home';stopPlay();updateUrl();render();window.scrollTo(0,0)}
 else if(el.dataset.stage!==undefined){state.stage=+el.dataset.stage;document.querySelectorAll('.stage').forEach((x,i)=>{x.classList.toggle('selected',i===state.stage);x.setAttribute('aria-pressed',String(i===state.stage))});$('#stage-detail').innerHTML=stageDetail()}
 else if(el.dataset.stageModal!==undefined)stageModal(+el.dataset.stageModal);
 else if(el.dataset.scene!==undefined){stopPlay();setScene(+el.dataset.scene)}
 else if(el.dataset.token){const t=el.dataset.token;$('#scene-caption').textContent=t==='目标'?'这个位置是模型要预测的目标。训练时，真实文本提供答案；生成文本时，模型根据概率选择 token。':`“${t}”在这里代表一个示意 token。真实切分方式由 tokenizer 决定；中文不一定逐词切分。`;document.querySelectorAll('.token').forEach(x=>x.classList.toggle('active',x===el))}
 else if(el.dataset.anchor)$(el.dataset.anchor)?.scrollIntoView({behavior:'smooth'});
 else if(el.dataset.answer){const right=el.dataset.answer==='B';state.quiz=el.dataset.answer;document.querySelectorAll('[data-answer]').forEach(x=>x.classList.remove('wrong','correct'));el.classList.add(right?'correct':'wrong');$('#quiz-feedback').textContent=right?'✓ 正确。预测误差通过梯度影响参数更新。这就是你在动画和小实验里看到的学习循环。':'再想一下：训练会改变模型内部的参数。它可能记住某些训练内容，但不能把整个学习机制理解成数据库检索。';if(right){state.completed=true;$('#completion-text').textContent='✓ 已完成理解检查';const bar=$('.progress-track i');if(bar)bar.style.width='16.7%';const note=$('.lesson-sidebar .mono');if(note)note.textContent='1 / 6 UNITS COMPLETED';toast('第一课理解检查完成 ✓')}}
 else if(el.dataset.action){switch(el.dataset.action){case'play':play();break;case'next-scene':stopPlay();setScene((state.scene+1)%4);break;case'board-pause':{const b=el.closest('.board');b.classList.toggle('paused');el.textContent=b.classList.contains('paused')?'▶':'Ⅱ';el.setAttribute('aria-label',b.classList.contains('paused')?'播放示意动画':'暂停示意动画');break}case'stage-open':stageModal(state.stage);break;case'close':closeModal();break;case'share':shareModal();break;case'video':videoModal();break;case'start-lesson':closeModal();go('lesson');break;case'resources':closeModal();go('resources');break;case'download':downloadCover();break;case'copy-draft':copy('模型在训练时，到底改变了什么？\n\n我把预测、比较和参数更新做成了一节可以亲手操作的图解课。无需训练背景，调整学习率就能看到变化。\n\nOpen Foundation Model Training · by Solo Unicorn\n'+location.origin+'/?page=lesson');break;case'copy-link':copy(location.origin+'/?variant='+state.variant+'&page=lesson');break}}});
document.addEventListener('input',e=>{if(e.target.id==='lr'){state.learningRate=Number(e.target.value);updateChart()}});
document.addEventListener('keydown',e=>{if($('.modal-backdrop')){if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const els=[...$('.modal').querySelectorAll('button,a,input,textarea,iframe')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(e.target.closest('input,textarea,[contenteditable]')||(document.documentElement.dataset.prototype==='false'||new URLSearchParams(location.search).get('layouts')!=='1'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const a=['A','B','C'];state.variant=a[(a.indexOf(state.variant)+(e.key==='ArrowRight'?1:2))%3];state.page='home';stopPlay();updateUrl();render();window.scrollTo(0,0)}});
render();
